const s=(e,a=()=>!0)=>e.sol.ok?Math.max(0,...e.sol.members.filter(t=>a(t.id)).map(t=>Math.max(Math.abs(t.maxM.value),Math.abs(t.minM.value)))):0,i=e=>s(e,a=>/^[AB]\d/.test(a)),n=(e,a,t)=>Number(e.ws)*Number(e[a])**2/(8*Number(e[t])),$=[{id:"l.rc-sys-archslab.parabola",xp:30,title:{en:"Turn the circular arch into a parabola under the full load: the bending all but vanishes",ar:"حوّل العقد الدائري لقطع مكافئ تحت الحمل الكامل: العزوم تقريباً بتختفي"},check:e=>e.template==="arch3h"&&e.params.shape==="parabola"&&e.params.span==="full"&&e.sol.ok&&s(e)<1}],o=[{id:"l.rc-sys-archslab.flat",xp:30,title:{en:"Flatten the slab to a rise of L/10 or less and read how the tie force grows",ar:"وطّي البلاطة لارتفاع L/10 أو أقل واقرا قوة الشداد زادت قد إيه"},check:e=>e.template==="archslab"&&e.params.sup==="tie"&&Number(e.params.L)/Number(e.params.h)>=10-1e-9&&e.sol.ok},{id:"l.rc-sys-archslab.half",xp:30,title:{en:"Put the live load on one half and compare the lab moment with pL²/64 in the Hand method",ar:"حط الحمل الحي على نص واحد وقارن عزم المعمل بـ pL²/64 في الحل اليدوي"},check:e=>e.template==="archslab"&&e.params.load==="half"&&e.tab==="hand"}],r=[{id:"l.rc-sys-archslab.posts",xp:40,title:{en:"Lean the posts along the springing force: no bending anywhere",ar:"ميّل الأعمدة مع قوة الارتكاز: مفيش عزوم في أي حتة"},check:e=>e.template==="archslab"&&e.params.sup==="posts"&&e.params.load==="full"&&e.sol.ok&&s(e)<.5},{id:"l.rc-sys-archslab.vposts",xp:30,title:{en:"Stand the slab on vertical posts and read the bending in the thin slab",ar:"وقّف البلاطة على أعمدة رأسية واقرا العزم في البلاطة الرفيعة"},check:e=>e.template==="archslab"&&e.params.sup==="vposts"&&e.sol.ok&&i(e)>50}],m=[{id:"l.rc-sys-archslab.balance",xp:40,title:{en:"Choose the rise of the second slab so that the interior beam feels less than 1.5 kN/m of thrust",ar:"اختار ارتفاع البلاطة التانية علشان الكمرة الوسطية تحس بأقل من 1.5 kN/m دفع"},hint:{en:"Equal thrusts need L₁²/h₁ = L₂²/h₂.",ar:"الدفعين يتساووا لما L₁²/h₁ = L₂²/h₂."},check:e=>e.template==="archslab"&&e.params.sup==="cont"&&Math.abs(n(e.params,"L","h")-n(e.params,"L2","h2"))<1.5}],h={sections:[{id:"idea",title:{en:"A slab that works like an arch",ar:"بلاطة بتشتغل زي العقد"},blocks:[{t:"p",text:{en:"An **arch slab** is a thin curved one-way slab spanning between two **end beams**, repeated along the hall. Its load — own weight, finishes and live load — is spread on plan, and the shape that carries such a load in pure compression, the **funicular**, is the inverted moment diagram of a simple beam under a uniform load: a **parabola**, not a circle. Shaped that way the slab has (almost) no bending, so 80–140 mm of concrete is enough to roof 8–18 m. It is analysed as a **1 m wide strip, three-hinged**: hinges at the two springings and at the crown.",ar:"الـ**بلاطة المقوّسة** بلاطة رفيعة منحنية في اتجاه واحد، بحرها بين **كمرتين طرفيتين**، ومتكررة على طول الصالة. حملها — الوزن الذاتي والتشطيبات والحمل الحي — مفروش على المسقط، والشكل اللي بيشيل حمل زي ده ضغط صافي، **الشكل الحبلي**، هو منحنى عزوم كمرة بسيطة تحت حمل موزع منتظم مقلوب: **قطع مكافئ**، مش دايرة. ولو اتشكّلت كده البلاطة (تقريباً) مالهاش عزوم، فـ 80–140 مم خرسانة كفاية تغطي 8–18 م. وبتتحلل كـ**شريحة عرضها 1 م بتلات مفصلات**: مفصلتين عند الارتكازين ومفصلة عند التاج."}},{t:"steps",items:[{en:"**Plain** — the slab alone between its end beams, ties at the column lines.",ar:"**عادية** — البلاطة لوحدها بين كمراتها الطرفية، والشدادات عند خطوط الأعمدة."},{en:"**With hangers** (250 × 250) — long ties sag under their own weight; hangers from the slab hold them up.",ar:"**بمعلّقات** (250 × 250) — الشدادات الطويلة بتترخّم من وزنها؛ ومعلّقات من البلاطة بتشيلها."},{en:"**With stiffeners** (ribs 250 × 400) — ribs cast with the slab cut it into narrow curved panels, so the thin slab has a short length free to buckle.",ar:"**بمقويات** (أعصاب 250 × 400) — أعصاب مصبوبة مع البلاطة بتقسمها لبواكي منحنية ضيقة، فالبلاطة الرفيعة يبقى الطول الحر اللي ممكن ينبعج فيها قصير."}]},{t:"p",text:{en:"In the lab below, an arch of 14 m with a rise of 2 m carries 5.0 kN/m² on plan. Shaped as a **circle** it bends by 2.49 kN·m/m; as a **parabola**, by nothing more than the small effect of its straight segments.",ar:"في المعمل اللي تحت، عقد 14 م وارتفاعه 2 م شايل 5.0 kN/m² على المسقط. ولو متشكّل **دايرة** بينحني بـ 2.49 kN·m/m؛ ولو **قطع مكافئ**، مفيش غير الأثر الصغير لأجزائه المستقيمة."}},{t:"lab",lab:"frame",height:470,props:{template:"arch3h",params:{L:14,f:2,w:5,P:0,shape:"circle",hinges:"3",span:"full"},lockTemplate:!0,missions:$},caption:{en:"A three-hinged arch under a load spread on plan: switch the shape between circle and parabola, or load one half.",ar:"عقد ثلاثي المفصلات تحت حمل مفروش على المسقط: بدّل الشكل بين دايرة وقطع مكافئ، أو حمّل نص واحد."}},{t:"quiz",q:{kind:"mcq",q:{en:"Why is an arch slab shaped as a parabola rather than a circle?",ar:"ليه البلاطة المقوّسة بتتشكّل قطع مكافئ مش دايرة؟"},options:[{en:"the parabola is the funicular of a load spread evenly on plan",ar:"القطع المكافئ هو الشكل الحبلي لحمل مفروش بالتساوي على المسقط"},{en:"a circle cannot be formed",ar:"الدايرة مينفعش تتعمل شدة ليها"},{en:"the parabola is shorter",ar:"القطع المكافئ أقصر"}],answer:0,explain:{en:"The thrust line of a uniform load on plan is the (inverted) parabolic moment diagram: an axis on it carries the load in compression only.",ar:"خط الضغط لحمل موزع منتظم على المسقط هو منحنى العزوم (القطع المكافئ) مقلوب: المحور اللي ماشي عليه بيشيل الحمل ضغط بس."}}}]},{id:"shape",title:{en:"Setting out the parabola",ar:"توقيع القطع المكافئ"},blocks:[{t:"eq",tex:["y = \\dfrac{4h\\,x(L - x)}{L^2},\\qquad Y = \\dfrac{4h\\,X^2}{L^2},\\qquad y = a x^2 + b x + c"],caption:{en:"x from a springing (height y above the springing line); X from the crown (drop Y below the crown); the general form through three known points.",ar:"x من ارتكاز (الارتفاع y فوق خط الارتكاز)؛ و X من التاج (النزول Y تحت التاج)؛ والصيغة العامة من تلات نقط معروفة."}},{t:"table",head:[{en:"Rule",ar:"القاعدة"},{en:"Value",ar:"القيمة"}],rows:[[{en:"span L",ar:"البحر L"},"8–18 m"],[{en:"rise h",ar:"الارتفاع h"},"L/6 – L/8"],[{en:"slab t_s",ar:"البلاطة t_s"},{en:"80–140 mm (120 typical)",ar:"80–140 مم (120 المعتاد)"}],[{en:"horizontal (end) beam width",ar:"عرض الكمرة الأفقية (الطرفية)"},"0.25–0.30 m"],[{en:"interior beam (vertical beam only)",ar:"الكمرة الوسطية (كمرة رأسية بس)"},{en:"b = 250 (≥ 400 between unequal slabs); t = S/12 + 150 mm",ar:"b = 250 (≥ 400 بين بلاطتين مختلفتين)؛ t = S/12 + 150 مم"}],[{en:"tie; hanger; stiffener",ar:"الشداد؛ المعلّق؛ المقوّي"},{en:"b × b; 250 × 250; 250 × 400",ar:"b × b؛ 250 × 250؛ 250 × 400"}],[{en:"columns",ar:"الأعمدة"},{en:"H/(10–12); × 1.5 without a tie",ar:"H/(10–12)؛ × 1.5 من غير شداد"}]]},{t:"p",text:{en:"**Example.** $L = 14$ m, $h = 2.0$ m ($L/7$). Every $L/10 = 1.4$ m from the springing: $y = 0.72,\\ 1.28,\\ 1.68,\\ 1.92,\\ 2.00$ m — that is $0.36h,\\ 0.64h,\\ 0.84h,\\ 0.96h,\\ h$, the same fractions for any parabola. In the form $y = ax^2 + bx + c$ through $(0, 0)$, $(7, 2)$ and $(14, 0)$: $a = -4h/L^2 = -0.0408$, $b = 4h/L = 0.5714$, $c = 0$. On site the points are set out on the formwork and joined with a flexible (French) curve.",ar:"**مثال.** $L = 14$ م، و $h = 2.0$ م ($L/7$). كل $L/10 = 1.4$ م من الارتكاز: $y = 0.72,\\ 1.28,\\ 1.68,\\ 1.92,\\ 2.00$ م — يعني $0.36h,\\ 0.64h,\\ 0.84h,\\ 0.96h,\\ h$، نفس النسب لأي قطع مكافئ. وبالصيغة $y = ax^2 + bx + c$ من $(0, 0)$ و $(7, 2)$ و $(14, 0)$: $a = -4h/L^2 = -0.0408$، و $b = 4h/L = 0.5714$، و $c = 0$. وفي الموقع النقط بتتوقّع على الشدة وبتتوصل بمنحنى مرن (فرنسي)."}},{t:"quiz",q:{kind:"num",q:{en:"Arch slab L = 16 m, rise 2.4 m. Height above the springing at a quarter of the span (m)?",ar:"بلاطة مقوّسة L = 16 م، والارتفاع 2.4 م. الارتفاع فوق الارتكاز عند ربع البحر (م)؟"},answer:1.8,tol:.003,unit:"m",explain:{en:"$y = 4\\times2.4\\times4\\times12/16^2 = 1.8$ m $= \\tfrac{3}{4}h$.",ar:"$y = 4\\times2.4\\times4\\times12/16^2 = 1.8$ م $= \\tfrac{3}{4}h$."}}}]},{id:"forces",title:{en:"The three-hinged strip",ar:"الشريحة ثلاثية المفصلات"},blocks:[{t:"p",text:{en:"Take a strip 1 m wide. Its load on plan is $w_s = 1.4(t_s\\gamma_c + F.C.) + 1.6\\,L.L.$ — on a curved roof the finishes are light (F.C. ≈ 0.5) and the live load small (≈ 0.5 kN/m²), so $w_s \\approx 5.0$–$5.7$ kN/m². Each springing takes $Y = w_sL/2$ vertically and the **thrust** $X$ horizontally; moments about the crown hinge give $X = w_sL^2/(8h)$. Their resultant $P$ is largest at the springings — and it points exactly along the slab there: $Y/X = 4h/L = \\tan\\theta$.",ar:"خد شريحة عرضها 1 م. حملها على المسقط $w_s = 1.4(t_s\\gamma_c + F.C.) + 1.6\\,L.L.$ — وعلى سقف منحني التشطيبات خفيفة (F.C. ≈ 0.5) والحمل الحي صغير (≈ 0.5 kN/m²)، فـ $w_s \\approx 5.0$–$5.7$ kN/m². كل ارتكاز بياخد $Y = w_sL/2$ رأسي و**الدفع** $X$ أفقي؛ والعزوم حوالين مفصلة التاج بتدّي $X = w_sL^2/(8h)$. ومحصلتهم $P$ أكبر ما تكون عند الارتكازات — ومتجهة بالظبط مع البلاطة هناك: $Y/X = 4h/L = \\tan\\theta$."}},{t:"eq",tex:["Y = \\dfrac{w_s L}{2},\\qquad X = \\dfrac{w_s L^2}{8h},\\qquad P = \\sqrt{X^2 + Y^2},\\qquad M = 0"],caption:{en:"Per metre of slab; M = 0 for the full uniform load on the parabola.",ar:"لكل متر بلاطة؛ و M = 0 للحمل المنتظم الكامل على القطع المكافئ."}},{t:"p",text:{en:"**Example.** $t_s = 100$ mm: $w_s = 1.4\\,(0.10\\times25 + 0.5) + 1.6\\times0.5 = 5.0$ kN/m². $Y = 5.0\\times14/2 = 35.0$, $X = 5.0\\times14^2/(8\\times2) = 61.25$, $P = \\sqrt{61.25^2 + 35.0^2} = 70.54$ kN/m; $Y/X = 0.571 = 4\\times2/14$ → $\\theta = 29.74^\\circ$.",ar:"**مثال.** $t_s = 100$ مم: $w_s = 1.4\\,(0.10\\times25 + 0.5) + 1.6\\times0.5 = 5.0$ kN/m². و $Y = 5.0\\times14/2 = 35.0$، و $X = 5.0\\times14^2/(8\\times2) = 61.25$، و $P = \\sqrt{61.25^2 + 35.0^2} = 70.54$ kN/m؛ و $Y/X = 0.571 = 4\\times2/14$ ← $\\theta = 29.74^\\circ$."}},{t:"lab",lab:"frame",height:470,props:{template:"archslab",lockTemplate:!0,missions:o},caption:{en:"A 1 m strip of the 14 m arch slab with its tie. Change the rise, the springings and the live-load pattern; the Hand method gives Y, X, P and the steel.",ar:"شريحة 1 م من البلاطة المقوّسة 14 م بشدادها. غيّر الارتفاع والارتكاز وتوزيع الحمل الحي؛ والحل اليدوي بيدّي Y و X و P والحديد."}},{t:"quiz",q:{kind:"num",q:{en:"Arch slab: w_s = 5.5 kN/m², L = 12 m, rise 2 m. Thrust X per metre (kN/m)?",ar:"بلاطة مقوّسة: w_s = 5.5 kN/m²، و L = 12 م، والارتفاع 2 م. الدفع X لكل متر (kN/m)؟"},answer:49.5,tol:.003,unit:"kN/m",explain:{en:"$X = 5.5\\times12^2/(8\\times2) = 49.5$ kN/m.",ar:"$X = 5.5\\times12^2/(8\\times2) = 49.5$ kN/m."}}}]},{id:"halfload",title:{en:"Live load on one half",ar:"الحمل الحي على نص واحد"},blocks:[{t:"p",text:{en:"The dead load $g_s = 1.4(t_s\\gamma_c + F.C.)$ is always on the whole span, but the live part $p_s = w_s - g_s$ may cover only one half. The load is then no longer funicular and the three-hinged strip bends — most at the quarter points, by $M = p_sL^2/64$. For our slab: $g_s = 4.2$, $p_s = 0.8$ kN/m² → $M = 0.8\\times14^2/64 = 2.45$ kN·m/m. Very small: with $N \\approx 58$ kN/m at the quarter point, $e = 2.45/58 = 0.042$ m; moved to the steel ($c = 25$ mm): $M_s = 58\\times(0.042 + 0.05 - 0.025) = 3.89$ kN·m/m, and $A_s = M_s/(J f_y d) - N/(f_y/\\gamma_s) < 0$ — no tension steel is needed, the minimum on both faces covers it.",ar:"الحمل الميت $g_s = 1.4(t_s\\gamma_c + F.C.)$ دايماً على البحر كله، بس الجزء الحي $p_s = w_s - g_s$ ممكن ييجي على نص واحد بس. ساعتها الحمل مابقاش حبلي والشريحة ثلاثية المفصلات بتنحني — أكتر حاجة عند ربع البحر، بمقدار $M = p_sL^2/64$. لبلاطتنا: $g_s = 4.2$، و $p_s = 0.8$ kN/m² ← $M = 0.8\\times14^2/64 = 2.45$ kN·m/m. صغير جداً: مع $N \\approx 58$ kN/m عند ربع البحر، $e = 2.45/58 = 0.042$ م؛ ولو نقلناها للحديد ($c = 25$ مم): $M_s = 58\\times(0.042 + 0.05 - 0.025) = 3.89$ kN·m/m، و $A_s = M_s/(J f_y d) - N/(f_y/\\gamma_s) < 0$ — مفيش حديد شد مطلوب، والحد الأدنى على الوشّين بيغطيه."}},{t:"eq",tex:["p_s = w_s - g_s,\\qquad M_{max} = \\dfrac{p_s\\,L^2}{64}"]},{t:"quiz",q:{kind:"num",q:{en:"w_s = 5.7 and g_s = 4.9 kN/m² on an arch slab of 16 m. Largest moment with the live load on one half (kN·m/m)?",ar:"w_s = 5.7 و g_s = 4.9 kN/m² على بلاطة مقوّسة 16 م. أكبر عزم والحمل الحي على نص واحد (kN·m/m)؟"},answer:3.2,tol:.003,unit:"kN·m/m",explain:{en:"$p_s = 0.8$; $0.8\\times16^2/64 = 3.2$ kN·m/m.",ar:"$p_s = 0.8$؛ و $0.8\\times16^2/64 = 3.2$ kN·m/m."}}}]},{id:"slab",title:{en:"Designing the slab: a strut per metre",ar:"تصميم البلاطة: عضو ضغط لكل متر"},blocks:[{t:"p",text:{en:"With (almost) no moment, each metre of slab is a short strut under $P$: $P_u = 0.35A_cf_{cu} + 0.67A_sf_y$. The concrete alone always has plenty of capacity, so the answer is the **minimum steel** of compression members, $0.8\\%\\,A_c$, split between the two faces and running in the span direction (with distribution bars across). **Example.** $0.35\\times100000\\times25 = 875$ kN $\\gg P = 70.5$ kN → $A_s < 0$ → $A_s = 0.008\\times100000 = 800$ mm²/m → 400 mm² on each face → **6Ø10/m** top and bottom. The same capacity serves any **pin-ended strut** — a member hinged at both ends that carries only axial compression, such as a strut between the tip of a cantilever and the head of a column: buckling neglected, $A_s \\ge 0.8\\%\\,A_c$. **Example.** A 250 × 250 strut carrying 120 kN: $0.35\\times62\\,500\\times25 = 546.9$ kN $\\gg 120$ kN → $A_s = 0.008\\times62\\,500 = 500$ mm² → 4Ø14 (616 mm²).",ar:"ومن غير عزوم (تقريباً)، كل متر بلاطة عبارة عن عضو ضغط قصير تحت $P$: $P_u = 0.35A_cf_{cu} + 0.67A_sf_y$. الخرسانة لوحدها دايماً عندها قدرة كتير، فالإجابة هي **الحد الأدنى للحديد** بتاع أعضاء الضغط، $0.8\\%\\,A_c$، متقسم على الوشّين وماشي في اتجاه البحر (وحديد توزيع بالعرض). **مثال.** $0.35\\times100000\\times25 = 875$ kN $\\gg P = 70.5$ kN ← $A_s < 0$ ← $A_s = 0.008\\times100000 = 800$ مم²/م ← 400 مم² على كل وش ← **6Ø10/م** فوق وتحت. ونفس القدرة دي بتنفع لأي **دعامة ضغط مفصلية الطرفين** — عضو مفصلي من الناحيتين شايل ضغط محوري بس، زي دعامة بين طرف كابولي وراس عمود: الانبعاج مهمل، و $A_s \\ge 0.8\\%\\,A_c$. **مثال.** دعامة 250 × 250 شايلة 120 kN: $0.35\\times62\\,500\\times25 = 546.9$ kN $\\gg 120$ kN ← $A_s = 0.008\\times62\\,500 = 500$ مم² ← 4Ø14 (616 مم²)."}},{t:"eq",tex:["P_u = 0.35\\,A_c\\,f_{cu} + 0.67\\,A_s\\,f_y,\\qquad A_{s,min} = 0.8\\%\\,b\\,t"]},{t:"quiz",q:{kind:"num",q:{en:"An arch slab 110 mm thick. Minimum steel on each face (mm² per metre)?",ar:"بلاطة مقوّسة تخانتها 110 مم. الحد الأدنى للحديد على كل وش (مم² لكل متر)؟"},answer:440,tol:.003,unit:"mm²",explain:{en:"$0.008\\times1000\\times110 = 880$ mm²/m in all, 440 on each face.",ar:"$0.008\\times1000\\times110 = 880$ مم²/م كلها، و 440 على كل وش."}}}]},{id:"endbeams",title:{en:"The end beams and the ties",ar:"الكمرات الطرفية والشدادات"},blocks:[{t:"p",text:{en:"The slab hands $Y$ and $X$ to an **L-shaped end beam**. Its **vertical leg** carries its own weight plus $Y$ and spans $S$ between the columns; its **horizontal leg** carries $X$ sideways and spans $S$ between the **ties**, one at every column line. Both are continuous: $M = wS^2/10$ at the first interior support, $wS^2/12$ inside. The column receives $R_{VL} = (o.w. + Y)\\,S$, the tie $R_{HL} = X\\,S$. The own weight of both legs is about 7.0 kN/m (ultimate). Where two slabs meet, the interior beam takes $2Y$ and is about $S/12 + 0.15$ m deep.",ar:"البلاطة بتسلّم $Y$ و $X$ لـ**كمرة طرفية على شكل L**. **رجلها الرأسية** بتشيل وزنها زائد $Y$ وبحرها $S$ بين الأعمدة؛ و**رجلها الأفقية** بتشيل $X$ أفقي وبحرها $S$ بين **الشدادات**، شداد عند كل خط أعمدة. والاتنين مستمرين: $M = wS^2/10$ عند أول ركيزة وسطية، و $wS^2/12$ جوه. والعمود بياخد $R_{VL} = (o.w. + Y)\\,S$، والشداد $R_{HL} = X\\,S$. ووزن الرجلين مع بعض حوالي 7.0 kN/m (أقصى). ولما بلاطتين يتقابلوا، الكمرة الوسطية بتاخد $2Y$ وعمقها حوالي $S/12 + 0.15$ م."}},{t:"eq",tex:["w_{VL} = o.w. + Y,\\qquad R_{VL} = w_{VL}\\,S,\\qquad w_{HL} = X,\\qquad T = R_{HL} = X\\,S","M = \\dfrac{wS^2}{10},\\ \\dfrac{wS^2}{12},\\qquad A_{s,tie} = \\dfrac{T}{f_y/\\gamma_s}"]},{t:"steps",items:[{en:"Columns and ties every $S = 5$ m. Vertical leg: $w_{VL} = 7.0 + 35.0 = 42.0$ kN/m → $R_{VL} = 210$ kN per column; $M = 42.0\\times25/10 = 105.0$ and $87.5$ kN·m.",ar:"الأعمدة والشدادات كل $S = 5$ م. الرجل الرأسية: $w_{VL} = 7.0 + 35.0 = 42.0$ kN/m ← $R_{VL} = 210$ kN لكل عمود؛ و $M = 42.0\\times25/10 = 105.0$ و $87.5$ kN·m."},{en:"Horizontal leg: $w_{HL} = 61.25$ kN/m → $M = 153.1$ and $127.6$ kN·m; tie force $T = 61.25\\times5 = 306.25$ kN → $A_s = 306.25\\times10^3/(400/1.15) = 880$ mm² → 4Ø18 in a 250 × 250 tie.",ar:"الرجل الأفقية: $w_{HL} = 61.25$ kN/m ← $M = 153.1$ و $127.6$ kN·m؛ وقوة الشداد $T = 61.25\\times5 = 306.25$ kN ← $A_s = 306.25\\times10^3/(400/1.15) = 880$ مم² ← 4Ø18 في شداد 250 × 250."},{en:"Sections ($f_{cu} = 25$, $f_y = 400$): vertical leg 250 × 550, $d = 500$: $C_1 = 3.86$, $J = 0.798$, $A_s = 658$ mm² → 4Ø16; horizontal leg 250 thick × 600 wide, $d = 550$: $C_1 = 3.51$, $J = 0.782$, $A_s = 890$ mm² → 4Ø18.",ar:"القطاعات ($f_{cu} = 25$، و $f_y = 400$): الرجل الرأسية 250 × 550، و $d = 500$: $C_1 = 3.86$، و $J = 0.798$، و $A_s = 658$ مم² ← 4Ø16؛ والرجل الأفقية تخانتها 250 وعرضها 600، و $d = 550$: $C_1 = 3.51$، و $J = 0.782$، و $A_s = 890$ مم² ← 4Ø18."}]},{t:"quiz",q:{kind:"num",q:{en:"X = 50 kN/m, columns and ties every 6 m. Force in one tie (kN)?",ar:"X = 50 kN/m، والأعمدة والشدادات كل 6 م. القوة في الشداد الواحد (kN)؟"},answer:300,tol:.003,unit:"kN",explain:{en:"$T = X\\,S = 50\\times6 = 300$ kN.",ar:"$T = X\\,S = 50\\times6 = 300$ kN."}}}]},{id:"notie",title:{en:"Without a tie — and posts along the thrust",ar:"من غير شداد — وأعمدة مايلة مع خط الضغط"},blocks:[{t:"p",text:{en:"Leave out the ties and every column is pushed at its head by $X\\,S$: a cantilever with $M = X\\,S\\,H$ at its base. The columns become 1.5 times deeper ($1.5H/12$ to $1.5H/10$) and their footings are shifted outwards. In our hall ($H = 5$ m): $M = 306.25\\times5 = 1531$ kN·m per column, against 0.42–0.50 m columns carrying only $R_{VL}$ when tied. Two other ways to deal with the thrust:",ar:"شيل الشدادات وكل عمود هيتزق من راسه بـ $X\\,S$: كابولي عزمه عند القاعدة $M = X\\,S\\,H$. الأعمدة بتبقى أعمق مرة ونص ($1.5H/12$ لـ $1.5H/10$) وقواعدها بتترحّل لبره. في صالتنا ($H = 5$ م): $M = 306.25\\times5 = 1531$ kN·m لكل عمود، قصاد أعمدة 0.42–0.50 م شايلة $R_{VL}$ بس لو فيه شداد. وفيه طريقتين تانيين للتعامل مع الدفع:"}},{t:"steps",items:[{en:"**Posts leaning along the springing force** ($\\tan\\theta = Y/X$): they just continue the thrust line down to the footings and stay in pure compression — $P\\,S = 70.54\\times5 = 352.7$ kN each. The footings still receive $X\\,S$ sideways: tie them together below ground.",ar:"**أعمدة مايلة مع قوة الارتكاز** ($\\tan\\theta = Y/X$): بتكمّل خط الضغط لتحت للقواعد وبتفضل ضغط صافي — $P\\,S = 70.54\\times5 = 352.7$ kN لكل واحد. والقواعد لسه بتاخد $X\\,S$ أفقي: اربطهم ببعض تحت الأرض."},{en:"**Vertical posts** pinned at the bottom: the thrust drops to $X' = w_sL^2/(8(h + H)) = 17.5$ kN/m, but the thrust line leaves the axis — the thin slab bends by 87.5 kN·m/m at the post heads and each post by $17.5\\times5\\times5 = 437.5$ kN·m.",ar:"**أعمدة رأسية** مفصلية من تحت: الدفع بينزل لـ $X' = w_sL^2/(8(h + H)) = 17.5$ kN/m، بس خط الضغط بيبعد عن المحور — البلاطة الرفيعة بتنحني بـ 87.5 kN·m/m عند روس الأعمدة، وكل عمود بـ $17.5\\times5\\times5 = 437.5$ kN·m."}]},{t:"p",text:{en:"**Beside other systems.** An untied arch slab next to simple girders: give each girder real supports — a real hinge on the arch side, a real roller at its far end — and the whole $X\\,S$ goes into the one column under the hinge and straight down to its footing; make that column about $1.5\\,t$ ($t$ = its usual depth) and shift its footing against the moment. Or keep the girders monolithic and make the arch-side column about $2.5\\,t$: its sway stiffness grows with $t^3$, so it draws $2.5^3/(2.5^3 + 1) = 94\\%$ of the push. In our hall ($X\\,S = 306.25$ kN, 1531 kN·m at the base of a 5 m column) a 0.45 m column becomes about 0.68 m on a real hinge, or about 1.13 m by stiffness. Between two-hinged frames an untied arch slab makes the frames sway, and only a full solution (superposition or virtual work) gives their moments — a tie is the practical answer. The same holds across a hall with low side bays, say 6 + 16 + 6 m with the arch slab over the 16 m: a tie across the middle bay keeps the side bays ordinary; without it they would have to become frames leaning along the thrust, an impractical shape. In every case the columns of a **tied** arch slab carry $P$ with only the additional moment of buckling $M_{add}$ (footings not shifted); those of an **untied** one carry $P$ with the external moment $M_{ext}$ of the thrust (deepened, footings shifted outwards).",ar:"**جنب أنظمة تانية.** بلاطة مقوّسة من غير شداد جنب كمرات بسيطة: ادّي كل كمرة ركائز حقيقية — مفصلة حقيقية ناحية العقد وركيزة متحركة حقيقية في طرفها التاني — فالـ $X\\,S$ كلها بتروح للعمود الواحد اللي تحت المفصلة ومنه للقاعدة على طول؛ خلّي العمود ده حوالي $1.5\\,t$ ($t$ = عمقه العادي) ورحّل قاعدته عكس العزم. أو سيب الكمرات مصبوبة مع الأعمدة وخلّي العمود اللي ناحية العقد حوالي $2.5\\,t$: جساءته للإزاحة الجانبية (Sway) بتكبر مع $t^3$، فبيسحب $2.5^3/(2.5^3 + 1) = 94\\%$ من الزقة. في صالتنا ($X\\,S = 306.25$ kN، و 1531 kN·m عند قاعدة عمود 5 م) العمود اللي عمقه 0.45 م بيبقى حوالي 0.68 م على مفصلة حقيقية، أو حوالي 1.13 م بالجساءة. وبين إطارات ذات مفصلين البلاطة المقوّسة من غير شداد بتعمل إزاحة جانبية (Sway) للإطارات، ومفيش غير الحل الكامل (التجميع أو الشغل الافتراضي) اللي بيدّي عزومهم — والشداد هو الحل العملي. ونفس الكلام في صالة ليها بواكي جانبية واطية، مثلاً 6 + 16 + 6 م والبلاطة المقوّسة فوق الـ 16 م: شداد بعرض الباكية الوسطانية بيسيب البواكي الجانبية عادية؛ ومن غيره كانت هتضطر تبقى إطارات مايلة مع خط الدفع، وده شكل مش عملي. وفي كل الحالات أعمدة البلاطة المقوّسة اللي **بشداد** بتشيل $P$ مع العزم الإضافي للانبعاج $M_{add}$ بس (من غير ترحيل للقواعد)؛ وأعمدة اللي **من غير شداد** بتشيل $P$ مع العزم الخارجي $M_{ext}$ من الدفع (بتتعمّق وقواعدها بتترحّل لبره)."}},{t:"lab",lab:"frame",height:470,props:{template:"archslab",params:{sup:"cols"},lockTemplate:!0,missions:r},caption:{en:"The same strip on two columns without a tie; switch to posts along the thrust or vertical posts.",ar:"نفس الشريحة على عمودين من غير شداد؛ وبدّل لأعمدة مايلة مع خط الضغط أو أعمدة رأسية."}},{t:"quiz",q:{kind:"num",q:{en:"No ties: X = 40 kN/m, columns every 6 m, 5 m high. Moment at the base of a column (kN·m)?",ar:"من غير شدادات: X = 40 kN/m، والأعمدة كل 6 م وارتفاعها 5 م. العزم عند قاعدة العمود (kN·m)؟"},answer:1200,tol:.003,unit:"kN·m",explain:{en:"$X\\,S\\,H = 40\\times6\\times5 = 1200$ kN·m.",ar:"$X\\,S\\,H = 40\\times6\\times5 = 1200$ kN·m."}}}]},{id:"posts",title:{en:"Posts, windows and the rise",ar:"القوائم والشبابيك والارتفاع"},blocks:[{t:"p",text:{en:"Posts that carry the springing stay in pure compression only if they follow the springing force: their slope must be $Y/X$. For a parabolic slab $Y/X = (w_sL/2)/(w_sL^2/8h) = 4h/L$, so the rule also works backwards: when the slope of the posts, $\\tan\\beta$ (rise over run), is fixed first, it fixes the rise of the slab.",ar:"القوائم اللي شايلة الارتكاز بتفضل ضغط صافي بس لو ماشية مع قوة الارتكاز: ميلها لازم يبقى $Y/X$. ولبلاطة قطع مكافئ $Y/X = (w_sL/2)/(w_sL^2/8h) = 4h/L$، فالقاعدة بتشتغل بالعكس كمان: لو ميل القوائم $\\tan\\beta$ (الرأسي على الأفقي) متحدد الأول، هو اللي بيحدد ارتفاع البلاطة."}},{t:"eq",tex:["h = \\dfrac{L}{4}\\,\\tan\\beta,\\qquad \\dfrac{L}{8} \\le h \\le \\dfrac{L}{6} \\;\\Rightarrow\\; 0.5 \\le \\tan\\beta \\le 0.667"],caption:{en:"tan β = rise/run of the posts; posts flatter than 1 : 2 (26.6°) or steeper than 2 : 3 (33.7°) give a rise outside the usual L/8 – L/6.",ar:"tan β = ميل القوائم (الرأسي/الأفقي)؛ قوائم أوطى من 1 : 2 (26.6°) أو أعلى من 2 : 3 (33.7°) بتدّي ارتفاع بره المدى المعتاد L/8 – L/6."}},{t:"p",text:{en:"**Example.** A 16 m arch slab must spring onto posts already set at 1 : 2 ($\\tan\\beta = 0.5$): $h = 16/4\\times0.5 = 2.0$ m $= L/8$ — check: $Y/X = 4\\times2.0/16 = 0.5$. Our 14 m slab read the other way: $4\\times2/14 = 0.571$, the $29.74^\\circ$ of its springing force.",ar:"**مثال.** بلاطة مقوّسة 16 م لازم ترتكز على قوائم متحطة بميل 1 : 2 ($\\tan\\beta = 0.5$): $h = 16/4\\times0.5 = 2.0$ م $= L/8$ — مراجعة: $Y/X = 4\\times2.0/16 = 0.5$. وبلاطتنا 14 م لو اتقرت بالعكس: $4\\times2/14 = 0.571$، يعني الـ $29.74^\\circ$ بتوع قوة ارتكازها."}},{t:"p",text:{en:"**The inclined end beam.** On such posts the end beam is turned into the plane of the springing force too, so slab, beam and posts carry $P$ along one line. Per metre it receives $w_i = P + o.w.\\cos\\theta_v$ — $\\theta_v$ = the angle of that plane from the **vertical** — and gives each post $R_i = w_i\\,S$ along the same line. Between the posts it is a continuous beam: hogging over them and sagging between, so top bars over the posts and bottom bars in the spans. **No tie** is added: a tie would pull $X$ out, turn the resultant vertical and move it off the posts' axis. **Example:** $P = 70.54$ kN/m, $\\theta_v = 90^\\circ - 29.74^\\circ = 60.26^\\circ$, a beam of 6.0 kN/m, posts every 5 m: $w_i = 70.54 + 6.0\\times0.496 = 73.52$ kN/m, $R_i = 367.6$ kN per post, $M = 73.52\\times5^2/10 = 183.8$ and $73.52\\times5^2/12 = 153.2$ kN·m.",ar:"**الكمرة الطرفية المايلة.** على قوائم زي دي الكمرة الطرفية كمان بتتلف في مستوى قوة الارتكاز، فالبلاطة والكمرة والقوائم بيشيلوا $P$ على خط واحد. لكل متر بتاخد $w_i = P + o.w.\\cos\\theta_v$ — و $\\theta_v$ = زاوية المستوى ده من **الرأسي** — وبتدّي كل قائم $R_i = w_i\\,S$ في نفس الاتجاه. وبين القوائم هي كمرة مستمرة: عزم سالب فوقها وموجب بينها، يعني حديد علوي فوق القوائم وسفلي في البحور. و**مفيش شداد** بيتحط: الشداد هيسحب $X$ ويخلّي المحصلة رأسية ويبعدها عن محور القوائم. **مثال:** $P = 70.54$ kN/m، و $\\theta_v = 90^\\circ - 29.74^\\circ = 60.26^\\circ$، وكمرة وزنها 6.0 kN/m، والقوائم كل 5 م: $w_i = 70.54 + 6.0\\times0.496 = 73.52$ kN/m، و $R_i = 367.6$ kN لكل قائم، و $M = 73.52\\times5^2/10 = 183.8$ و $73.52\\times5^2/12 = 153.2$ kN·m."}},{t:"eq",tex:["w_i = P + o.w.\\cos\\theta_v,\\qquad R_i = w_i\\,S"],caption:{en:"P = √(X² + Y²) per metre; θ_v = angle of the beam plane (and of the posts) from the vertical; S = post spacing.",ar:"P = √(X² + Y²) لكل متر؛ و θ_v = زاوية مستوى الكمرة (والقوائم) من الرأسي؛ و S = المسافة بين القوائم."}},{t:"p",text:{en:"**A vertical window.** When the glazing under the springing must be vertical, the post is best made vertical too — the natural choice, though not a rule — and the springing force cannot follow it. A post is strong along its axis only, so the force it receives must be vertical: a **tie** at the springing level, across the hall at the head of the windows, takes $X$, and the post carries $(o.w. + Y)\\,S$ alone. Without a tie the post is pushed at its head and bends: it must be thickened and designed as part of the frame below it — usually a **cantilever frame** whose arm carries the post.",ar:"**شباك رأسي.** لما الإزاز اللي تحت الارتكاز لازم يبقى رأسي، الأفضل إن القائم يبقى رأسي هو كمان — الاختيار الطبيعي، مش شرط — وقوة الارتكاز مش هتقدر تمشي معاه. والقائم قوي في اتجاه محوره بس، فالقوة اللي بياخدها لازم تبقى رأسية: **شداد** عند منسوب الارتكاز، بعرض الصالة عند راس الشبابيك، بياخد $X$، والقائم بيشيل $(o.w. + Y)\\,S$ لوحدها. ومن غير شداد القائم بيتزق من راسه وبينحني: لازم يتخن ويتصمم كجزء من الإطار اللي تحته — عادة **إطار كابولي** ذراعه شايل القائم."}},{t:"steps",items:[{en:"**Example.** Our 14 m slab springs on 2.0 m vertical posts standing on the tips of 2.5 m arms of cantilever frames; the arms reach in towards the hall from columns 5 m high, every 5 m, so the thrust at a post head points back towards its column.",ar:"**مثال.** بلاطتنا 14 م مرتكزة على قوائم رأسية 2.0 م واقفة على أطراف ذراعات طولها 2.5 م لإطارات كابولي؛ والذراعات طالعة لجوه ناحية الصالة من أعمدة ارتفاعها 5 م، كل 5 م، فالدفع عند راس القائم متجه راجع ناحية عموده."},{en:"**Tied:** post $N = (7.0 + 35.0)\\times5 = 210$ kN, no moment; the arm hogs by $210\\times2.5 = 525$ kN·m at its root, and the column carries that same moment down to its base (footing shifted towards the arm).",ar:"**بشداد:** القائم $N = (7.0 + 35.0)\\times5 = 210$ kN، من غير عزم؛ والذراع عليه عزم سالب $210\\times2.5 = 525$ kN·m عند جذره، والعمود شايل نفس العزم ده لحد قاعدته (القاعدة مترحّلة ناحية الذراع)."},{en:"**Untied:** the post head is pushed outwards, towards the column, by $X\\,S = 61.25\\times5 = 306.25$ kN: the post bends by $306.25\\times2.0 = 612.5$ kN·m at its foot; at the arm root the push beats the load, $612.5 - 525 = 87.5$ kN·m the other way; the column moment grows from 87.5 at its top to $87.5 + 306.25\\times5 = 1618.75$ kN·m at its base (footing shifted outwards).",ar:"**من غير شداد:** راس القائم بتتزق لبره، ناحية العمود، بـ $X\\,S = 61.25\\times5 = 306.25$ kN: القائم بينحني بـ $306.25\\times2.0 = 612.5$ kN·m عند رجله؛ وعند جذر الذراع الزقة بتغلب الحمل، $612.5 - 525 = 87.5$ kN·m في الاتجاه العكسي؛ وعزم العمود بيكبر من 87.5 عند راسه لـ $87.5 + 306.25\\times5 = 1618.75$ kN·m عند قاعدته (القاعدة مترحّلة لبره)."},{en:"So the tie is the usual answer under a vertical window; without it post, arm and column are one frame designed for $M$ and $N$.",ar:"يعني الشداد هو الحل المعتاد مع الشباك الرأسي؛ ومن غيره القائم والذراع والعمود إطار واحد بيتصمم على $M$ و $N$."}]},{t:"quiz",q:{kind:"num",q:{en:"A 12 m arch slab must spring onto posts sloping 2 (up) : 3 (across). Rise h of the slab (m)?",ar:"بلاطة مقوّسة 12 م لازم ترتكز على قوائم ميلها 2 (لفوق) : 3 (بالعرض). ارتفاع البلاطة h (م)؟"},answer:2,tol:.003,unit:"m",explain:{en:"$h = (L/4)\\tan\\beta = 3\\times2/3 = 2.0$ m — between $L/8 = 1.5$ and $L/6 = 2.0$.",ar:"$h = (L/4)\\tan\\beta = 3\\times2/3 = 2.0$ م — بين $L/8 = 1.5$ و $L/6 = 2.0$."}}}]},{id:"continuous",title:{en:"Continuous arch slabs",ar:"البلاطات المقوّسة المستمرة"},blocks:[{t:"p",text:{en:"Several arch slabs side by side share their interior beams. With **equal** spans and rises the two thrusts cancel on the interior beam, which carries only $2Y$ + its weight. With **unequal** slabs the difference $\\Delta X = X_2 - X_1$ pushes the interior beam sideways: it bends about both axes (vertical $2Y$, horizontal $\\Delta X$), and the ties — if any — at the ends take the outer thrusts. Choose the rises so that $L_1^2/h_1 = L_2^2/h_2$ and $\\Delta X$ disappears.",ar:"كذا بلاطة مقوّسة جنب بعض بيشتركوا في الكمرات الوسطية. لو البحور والارتفاعات **متساوية** الدفعين بيلغوا بعض على الكمرة الوسطية، ودي بتشيل $2Y$ + وزنها بس. ولو البلاطات **مختلفة** الفرق $\\Delta X = X_2 - X_1$ بيزق الكمرة الوسطية لجنب: بتنحني في الاتجاهين (رأسي $2Y$، وأفقي $\\Delta X$)، والشدادات — لو موجودة — عند الأطراف بتاخد الدفع الخارجي. اختار الارتفاعات علشان $L_1^2/h_1 = L_2^2/h_2$ و $\\Delta X$ يختفي."}},{t:"eq",tex:["X_1 = \\dfrac{w_s L_1^2}{8h_1},\\qquad X_2 = \\dfrac{w_s L_2^2}{8h_2},\\qquad \\Delta X = X_2 - X_1"]},{t:"p",text:{en:"**Example.** Next to our 14 m slab ($X_1 = 61.25$ kN/m) comes a 10 m slab with $h_2 = 1.5$ m: $X_2 = 5.0\\times10^2/(8\\times1.5) = 41.67$ kN/m, $\\Delta X = 19.58$ kN/m. With $S = 5$ m the interior beam bends sideways by $19.58\\times25/10 = 49.0$ kN·m and vertically ($w = 7.0 + 35.0 + 25.0 = 67.0$ kN/m) by 167.5 kN·m. With $h_2 = 2.0\\times(10/14)^2 = 1.02$ m the thrusts would balance.",ar:"**مثال.** جنب بلاطتنا 14 م ($X_1 = 61.25$ kN/m) بلاطة 10 م بـ $h_2 = 1.5$ م: $X_2 = 5.0\\times10^2/(8\\times1.5) = 41.67$ kN/m، و $\\Delta X = 19.58$ kN/m. ومع $S = 5$ م الكمرة الوسطية بتنحني أفقي بـ $19.58\\times25/10 = 49.0$ kN·m ورأسي ($w = 7.0 + 35.0 + 25.0 = 67.0$ kN/m) بـ 167.5 kN·m. ولو $h_2 = 2.0\\times(10/14)^2 = 1.02$ م الدفعين كانوا هيتوازنوا."}},{t:"lab",lab:"frame",height:470,props:{template:"archslab",params:{sup:"cont"},lockTemplate:!0,missions:m},caption:{en:"Two arch slabs on one interior support: its horizontal reaction is ΔX.",ar:"بلاطتين مقوّستين على ركيزة وسطية واحدة: رد فعلها الأفقي هو ΔX."}},{t:"quiz",q:{kind:"num",q:{en:"X₁ = 60 kN/m on one side; the other slab: w_s = 5 kN/m², L₂ = 12 m, h₂ = 2 m. ΔX on the interior beam (kN/m)?",ar:"X₁ = 60 kN/m من ناحية؛ والبلاطة التانية: w_s = 5 kN/m²، و L₂ = 12 م، و h₂ = 2 م. ΔX على الكمرة الوسطية (kN/m)؟"},answer:15,tol:.003,unit:"kN/m",explain:{en:"$X_2 = 5\\times144/16 = 45$; $60 - 45 = 15$ kN/m.",ar:"$X_2 = 5\\times144/16 = 45$؛ و $60 - 45 = 15$ kN/m."}}}]},{id:"lines",title:{en:"Line by line: end beams, interior beams and columns",ar:"خط بخط: الكمرات الطرفية والوسطية والأعمدة"},blocks:[{t:"p",text:{en:"Across a hall of arch slabs, name the members by their lines: **B1/C1** the end beam and its columns, **B2/C2** an interior beam and its columns. Per metre of slab $Y = w_sL/2$ and $X = w_sL^2/(8h)$; $S$ is the column spacing, $o.w.$ the beam's own weight per metre and $H$ the column height.",ar:"في صالة فيها بلاطات مقوّسة، سمّي العناصر بخطوطها: **B1/C1** الكمرة الطرفية وأعمدتها، و**B2/C2** كمرة وسطية وأعمدتها. لكل متر بلاطة $Y = w_sL/2$ و $X = w_sL^2/(8h)$؛ و $S$ المسافة بين الأعمدة، و $o.w.$ وزن الكمرة لكل متر، و $H$ ارتفاع العمود."}},{t:"table",head:[{en:"Line",ar:"الخط"},{en:"Beam",ar:"الكمرة"},{en:"Load on the beam",ar:"الحمل على الكمرة"},{en:"Column forces (every S)",ar:"قوى العمود (كل S)"},{en:"Column depth",ar:"عمق العمود"}],rows:[[{en:"B1/C1 — end, tied",ar:"B1/C1 — طرفي، بشداد"},{en:"L-shaped: vertical + horizontal leg",ar:"على شكل L: رجل رأسية + رجل أفقية"},{en:"$w_{VL} = o.w. + Y$; $w_{HL} = X$, tie $T = X\\,S$",ar:"$w_{VL} = o.w. + Y$؛ و $w_{HL} = X$، والشداد $T = X\\,S$"},{en:"$R_{VL} = (o.w. + Y)\\,S$; no moment, footing not shifted",ar:"$R_{VL} = (o.w. + Y)\\,S$؛ من غير عزم، والقاعدة من غير ترحيل"},"$H/(10 \\to 12)$"],[{en:"B1/C1 — end, untied",ar:"B1/C1 — طرفي، من غير شداد"},{en:"L-shaped",ar:"على شكل L"},{en:"$w_{VL} = o.w. + Y$; $w_{HL} = X$",ar:"$w_{VL} = o.w. + Y$؛ و $w_{HL} = X$"},{en:"$R_{VL} = (o.w. + Y)\\,S$, $R_{HL} = X\\,S$ → $M = X\\,S\\,H$; footing shifted outwards",ar:"$R_{VL} = (o.w. + Y)\\,S$، و $R_{HL} = X\\,S$ ← $M = X\\,S\\,H$؛ والقاعدة مترحّلة لبره"},"$1.5\\,H/(10 \\to 12)$"],[{en:"B2/C2 — interior, equal slabs",ar:"B2/C2 — وسطي، بلاطات متساوية"},{en:"vertical beam only: $b = 250$, $t = S/12 + 150$ mm",ar:"كمرة رأسية بس: $b = 250$، و $t = S/12 + 150$ مم"},{en:"$w_{VL} = o.w. + 2Y$; the thrusts cancel",ar:"$w_{VL} = o.w. + 2Y$؛ والدفعين بيلغوا بعض"},{en:"$R_{VL} = (o.w. + 2Y)\\,S$; no moment, no shift",ar:"$R_{VL} = (o.w. + 2Y)\\,S$؛ من غير عزم ولا ترحيل"},"$H/(10 \\to 12)$"],[{en:"B2/C2 — interior, unequal slabs",ar:"B2/C2 — وسطي، بلاطات مختلفة"},{en:"vertical beam only: $b \\ge 400$, $t = S/12 + 150$ mm",ar:"كمرة رأسية بس: $b \\ge 400$، و $t = S/12 + 150$ مم"},{en:"$w_{VL} = o.w. + Y_1 + Y_2$; $w_{HL} = \\Delta X = X_2 - X_1$ — bending about both axes",ar:"$w_{VL} = o.w. + Y_1 + Y_2$؛ و $w_{HL} = \\Delta X = X_2 - X_1$ — عزم في الاتجاهين"},{en:"$R_{VL} = (o.w. + Y_1 + Y_2)\\,S$, $R_{HL} = \\Delta X\\,S$ → designed for $M$ and $P$",ar:"$R_{VL} = (o.w. + Y_1 + Y_2)\\,S$، و $R_{HL} = \\Delta X\\,S$ ← بيتصمم على $M$ و $P$"},{en:"from M and P",ar:"من M و P"}]],caption:{en:"Tied: the columns carry P with only the additional moment of buckling M_add. Untied: P with the external moment M_ext of the thrust.",ar:"بشداد: الأعمدة بتشيل P مع العزم الإضافي للانبعاج M_add بس. ومن غير شداد: P مع العزم الخارجي M_ext من الدفع."}},{t:"p",text:{en:"Why a **vertical beam only** inside? The horizontal leg of an end beam exists to carry $X$ sideways to the ties. Between two slabs the thrusts meet head on, so with equal slabs only the vertical load is left — a plain rectangular beam, like the Y-beam of a saw-tooth roof, 250 wide and $S/12 + 150$ mm deep. With unequal slabs the difference $\\Delta X$ still bends it sideways, so it is made at least 400 mm wide and designed for bending about both axes. **At an expansion joint** the slabs end on twin beams and twin columns sharing one footing: turn the horizontal leg of each L-beam **inwards**, away from the joint, or drop the leg and use a vertical beam only — usually 400 wide — designed for both loads together.",ar:"ليه **كمرة رأسية بس** جوه؟ الرجل الأفقية للكمرة الطرفية موجودة علشان تشيل $X$ أفقي للشدادات. لكن بين بلاطتين الدفعين بيتقابلوا وش لوش، فلو البلاطات متساوية مفيش غير الحمل الرأسي — كمرة مستطيلة عادية، زي كمرة Y في السقف المنشاري، عرضها 250 وعمقها $S/12 + 150$ مم. ولو البلاطات مختلفة الفرق $\\Delta X$ لسه بيحنيها أفقي، فبتتعمل بعرض 400 مم على الأقل وبتتصمم على عزم في الاتجاهين. و**عند فاصل التمدد** البلاطات بتنتهي على كمرتين توأم وعمودين توأم على قاعدة واحدة: يا إما تلف الرجل الأفقية لكل كمرة L **لجوه**، بعيد عن الفاصل، يا إما تشيل الرجل وتستخدم كمرة رأسية بس — عرضها عادة 400 — بتتصمم على الحملين مع بعض."}},{t:"steps",items:[{en:"**Example** — the hall of the previous section: the 14 m slab ($h = 2.0$) beside the 10 m slab ($h = 1.5$), $w_s = 5.0$ kN/m², $S = 5$ m, columns $H = 5$ m. **B1/C1** on the 14 m side: $w_{VL} = 7.0 + 35.0 = 42.0$ kN/m → $R_{VL} = 210$ kN, a 0.42–0.50 m column when tied; untied it also takes $X\\,S = 306.25$ kN and 1531 kN·m and grows to 0.63–0.75 m. On the 10 m side: $R_{VL} = (7.0 + 25.0)\\times5 = 160$ kN; untied $41.67\\times5 = 208.3$ kN and 1041.7 kN·m.",ar:"**مثال** — صالة القسم اللي فات: البلاطة 14 م ($h = 2.0$) جنب البلاطة 10 م ($h = 1.5$)، و $w_s = 5.0$ kN/m²، و $S = 5$ م، والأعمدة $H = 5$ م. **B1/C1** ناحية الـ 14 م: $w_{VL} = 7.0 + 35.0 = 42.0$ kN/m ← $R_{VL} = 210$ kN، وعمود 0.42–0.50 م لو فيه شداد؛ ومن غير شداد بياخد كمان $X\\,S = 306.25$ kN و 1531 kN·m ويكبر لـ 0.63–0.75 م. وناحية الـ 10 م: $R_{VL} = (7.0 + 25.0)\\times5 = 160$ kN؛ ومن غير شداد $41.67\\times5 = 208.3$ kN و 1041.7 kN·m."},{en:"**B2**: unequal slabs → a vertical beam only, 400 wide, $t = 5/12 + 0.15 = 0.567$ → 0.60 m, weighing $1.4\\times0.4\\times0.6\\times25 = 8.4$ kN/m: $w_{VL} = 8.4 + 35.0 + 25.0 = 68.4$ kN/m ($M = 68.4\\times25/10 = 171.0$ kN·m) and $w_{HL} = \\Delta X = 19.58$ kN/m (49.0 kN·m sideways).",ar:"**B2**: بلاطات مختلفة ← كمرة رأسية بس، عرضها 400، و $t = 5/12 + 0.15 = 0.567$ ← 0.60 م، ووزنها $1.4\\times0.4\\times0.6\\times25 = 8.4$ kN/m: $w_{VL} = 8.4 + 35.0 + 25.0 = 68.4$ kN/m ($M = 68.4\\times25/10 = 171.0$ kN·m) و $w_{HL} = \\Delta X = 19.58$ kN/m (49.0 kN·m أفقي)."},{en:"**C2**: $R_{VL} = 68.4\\times5 = 342$ kN and $R_{HL} = 19.58\\times5 = 97.9$ kN at its head — $97.9\\times5 = 489.6$ kN·m at the base of a 5 m column, designed for $M$ and $P$. Between two equal 14 m slabs the beam would be 250 wide ($o.w. = 1.4\\times0.25\\times0.6\\times25 = 5.25$ kN/m): $R_{VL} = (5.25 + 70.0)\\times5 = 376.25$ kN and no moment.",ar:"**C2**: $R_{VL} = 68.4\\times5 = 342$ kN و $R_{HL} = 19.58\\times5 = 97.9$ kN عند راسه — $97.9\\times5 = 489.6$ kN·m عند قاعدة عمود 5 م، بيتصمم على $M$ و $P$. وبين بلاطتين متساويتين 14 م الكمرة كانت هتبقى بعرض 250 ($o.w. = 1.4\\times0.25\\times0.6\\times25 = 5.25$ kN/m): $R_{VL} = (5.25 + 70.0)\\times5 = 376.25$ kN ومن غير عزم."}]},{t:"p",text:{en:"The same bookkeeping goes on when arch slabs sit on other systems: small arch slabs between beams carried by arch girders push the end beams along the girders, and each girder's own tie takes that $X\\,S$ as well, $T = 0.95\\,M_0/H + X\\,S$ (the arch-girder episode). An annex of arch slabs beside such a hall lands its edge beams on the end arch girder: each continuous edge beam hands it only its end reaction, taken on the safe side as $0.45\\,w_1\\,S$ (the exact value is $0.375$–$0.40\\,w_1\\,S$), and the annex's thrust goes into the girder's tie — one **common tie** for both.",ar:"ونفس الحسبة بتكمل لما البلاطات المقوّسة تركب على أنظمة تانية: بلاطات مقوّسة صغيرة بين كمرات شايلاها كمرات مقوّسة بتزق الكمرات الطرفية في اتجاه الكمرات المقوّسة، وشداد كل كمرة مقوّسة بياخد الـ $X\\,S$ دي كمان، $T = 0.95\\,M_0/H + X\\,S$ (حلقة الكمرات المقوّسة). وملحق بلاطات مقوّسة جنب صالة زي دي بيرمي كمراته الطرفية على الكمرة المقوّسة الطرفية: كل كمرة طرفية مستمرة بتسلّمها رد فعلها الطرفي بس، وبيتاخد في ناحية الأمان $0.45\\,w_1\\,S$ (القيمة المظبوطة $0.375$–$0.40\\,w_1\\,S$)، ودفع الملحق بيروح لشداد الكمرة المقوّسة — **شداد مشترك** للاتنين."}},{t:"quiz",q:{kind:"num",q:{en:"Two equal arch slabs meet on an interior beam; columns every 6 m. Depth of that vertical beam by the rule (m)?",ar:"بلاطتين مقوّستين متساويتين بيتقابلوا على كمرة وسطية؛ والأعمدة كل 6 م. عمق الكمرة الرأسية دي بالقاعدة (م)؟"},answer:.65,tol:.003,unit:"m",explain:{en:"$t = S/12 + 0.15 = 6/12 + 0.15 = 0.65$ m, with $b = 250$ mm (400 if the slabs differ).",ar:"$t = S/12 + 0.15 = 6/12 + 0.15 = 0.65$ م، مع $b = 250$ مم (400 لو البلاطتين مختلفتين)."}}}]},{id:"horizontal",title:{en:"A horizontal strip between arch slabs",ar:"شريحة أفقية بين البلاطات المقوّسة"},blocks:[{t:"p",text:{en:"Arch slabs are often separated by **horizontal strips** — a walkway, a gutter, a flat bay. Where a horizontal slab meets the springing of an arch slab no horizontal (L-leg) beam is needed: the horizontal slab itself is the horizontal beam. It takes $X$ in its own plane and hands it on — to the next arch slab, or to the tie (the same happens beside a saw-tooth slab). The price: the slab is now compressed as well as bent.",ar:"البلاطات المقوّسة كتير بيفصل بينها **شرايح أفقية** — ممشى، أو مزراب، أو باكية أفقية. وعند المكان اللي البلاطة الأفقية بتقابل فيه ارتكاز البلاطة المقوّسة مش محتاجين كمرة أفقية (رجل الـ L): البلاطة الأفقية نفسها هي الكمرة الأفقية. بتاخد $X$ في مستواها وبتسلّمها — للبلاطة المقوّسة اللي بعدها، أو للشداد (ونفس الكلام جنب البلاطة المنشارية). والتمن: البلاطة بقت مضغوطة ومنحنية مع بعض."}},{t:"steps",items:[{en:"**Thickness:** about **50 mm more** than its load alone would need, against buckling.",ar:"**التخانة:** حوالي **50 مم زيادة** عن اللي حملها لوحده محتاجه، ضد الانبعاج."},{en:"**Steel:** **two equal meshes**, top and bottom (symmetric steel).",ar:"**الحديد:** **شبكتين متساويتين**، فوق وتحت (حديد متماثل)."},{en:"**Forces per 1 m strip:** the simple-span moment of its own load, with the thrust as normal force. An arch slab on **one** side: the normal force falls linearly from $X$ at that edge to zero, so the mid-span section (largest $M$) takes $P = X/2$. Arch slabs on **both** sides: $P = X$ all along.",ar:"**القوى لكل شريحة 1 م:** عزم البحر البسيط من حملها، مع الدفع كقوة عمودية. لو فيه بلاطة مقوّسة من ناحية **واحدة**: القوة العمودية بتقل خطياً من $X$ عند الحرف ده لصفر، فقطاع نص البحر (أكبر $M$) بياخد $P = X/2$. ولو فيه بلاطات مقوّسة على **الناحيتين**: $P = X$ على طولها."},{en:"**Design** for $M$ and $P$ with the interaction diagram — after the usual first check: when $K = P/(f_{cu}b\\,t) \\le 0.04$ the thrust is neglected and the strip is designed for $M$ alone.",ar:"**التصميم** على $M$ و $P$ بمنحنى التفاعل — بعد المراجعة الأولى المعتادة: لما $K = P/(f_{cu}b\\,t) \\le 0.04$ الدفع بيتهمل والشريحة بتتصمم على $M$ لوحده."}]},{t:"eq",tex:["M = \\dfrac{w_s\\,a^2}{8},\\qquad P = \\dfrac{X}{2}\\;\\;(1),\\qquad P = X\\;\\;(2)"],caption:{en:"a = span of the horizontal strip; (1) an arch slab on one side, at mid-span; (2) arch slabs on both sides.",ar:"a = بحر الشريحة الأفقية؛ (1) بلاطة مقوّسة من ناحية واحدة، عند نص البحر؛ (2) بلاطات مقوّسة من الناحيتين."}},{t:"p",text:{en:"**Example.** A 3.0 m horizontal strip between two of our 14 m arch slabs ($X = 61.25$ kN/m). Say 110 mm would carry its load alone; with the thrust it gets 160 mm. With F.C. = 1.5 and L.L. = 1.0 kN/m²: $w_s = 1.4\\,(0.16\\times25 + 1.5) + 1.6\\times1.0 = 9.3$ kN/m², $M = 9.3\\times3^2/8 = 10.46$ kN·m/m with $P = 61.25$ kN/m. $K = 61\\,250/(25\\times1000\\times160) = 0.0153 < 0.04$ (and $e/t = 0.171/0.16 = 1.07$, a large eccentricity): the thrust is too small to count, so the strip is designed for $M$ alone — $d = 135$ mm, $C_1 = 6.6$, $J = 0.826$, $A_s = 10.46\\times10^6/(0.826\\times400\\times135) = 235$ mm²/m. Both meshes take it, and the slab minimum for high-tensile steel governs: **5Ø10/m top and bottom** (393 mm²). The thrust shows in the extra 50 mm and in the equal meshes. With an arch slab on one side only, $P = 30.63$ kN/m at mid-span — smaller still. Only a much heavier thrust ($K > 0.04$ with $e/t < 0.5$) brings in the chart: $A_s = A_s' = \\rho\\,f_{cu}10^{-4}\\,b\\,t$ with $\\rho \\ge 1$, and at least $0.8\\%\\,b\\,t$ in all.",ar:"**مثال.** شريحة أفقية 3.0 م بين بلاطتين من بلاطاتنا الـ 14 م ($X = 61.25$ kN/m). لنفرض إن 110 مم كانت هتشيل حملها لوحدها؛ ومع الدفع بتبقى 160 مم. وبـ F.C. = 1.5 و L.L. = 1.0 kN/m²: $w_s = 1.4\\,(0.16\\times25 + 1.5) + 1.6\\times1.0 = 9.3$ kN/m²، و $M = 9.3\\times3^2/8 = 10.46$ kN·m/m مع $P = 61.25$ kN/m. و $K = 61\\,250/(25\\times1000\\times160) = 0.0153 < 0.04$ (و $e/t = 0.171/0.16 = 1.07$، لامركزية كبيرة): الدفع أصغر من إنه يتحسب، فالشريحة بتتصمم على $M$ لوحده — $d = 135$ مم، و $C_1 = 6.6$، و $J = 0.826$، و $A_s = 10.46\\times10^6/(0.826\\times400\\times135) = 235$ مم²/م. والشبكتين بياخدوها، والحد الأدنى للبلاطات مع الحديد عالي المقاومة هو اللي بيحكم: **5Ø10/م فوق وتحت** (393 مم²). والدفع بيبان في الـ 50 مم الزيادة وفي الشبكتين المتساويتين. ولو البلاطة المقوّسة من ناحية واحدة بس، $P = 30.63$ kN/m في نص البحر — أصغر كمان. ومفيش غير دفع أتقل بكتير ($K > 0.04$ مع $e/t < 0.5$) هو اللي بيدخّل المنحنى: $A_s = A_s' = \\rho\\,f_{cu}10^{-4}\\,b\\,t$ مع $\\rho \\ge 1$، و $0.8\\%\\,b\\,t$ على الأقل في المجموع."}},{t:"quiz",q:{kind:"num",q:{en:"A horizontal strip has an arch slab with X = 56 kN/m on one side only. Normal force P for its mid-span design (kN/m)?",ar:"شريحة أفقية جنبها بلاطة مقوّسة X = 56 kN/m من ناحية واحدة بس. القوة العمودية P لتصميم نص البحر (kN/m)؟"},answer:28,tol:.003,unit:"kN/m",explain:{en:"The normal force falls from X at the arch side to zero: $P = X/2 = 28$ kN/m at mid-span (with arch slabs on both sides it would be $X = 56$).",ar:"القوة العمودية بتقل من X ناحية العقد لصفر: $P = X/2 = 28$ kN/m في نص البحر (ولو فيه بلاطات مقوّسة من الناحيتين تبقى $X = 56$)."}}}]},{id:"apply",title:{en:"Your building: the workshop roof as an arch slab",ar:"مبناك: سقف الورشة كبلاطة مقوّسة"},blocks:[{t:"p",text:{en:"The workshop spans 12 m and its steel roof rises 1.6 m from the eaves to the ridge — $L/h = 7.5$, right in the range of arch slabs. Roof it in RC with a **100 mm parabolic slab**, ties at the column lines every $S = 6$ m (at the eaves, where the bottom chords of the steel trusses are today) and L-shaped end beams along the two long walls.",ar:"الورشة بحرها 12 م وسقفها المعدني بيطلع 1.6 م من الجمالون الطرفي للقمة — $L/h = 7.5$، جوه مدى البلاطات المقوّسة بالظبط. سقّفها خرسانة بـ**بلاطة قطع مكافئ 100 مم**، وشدادات عند خطوط الأعمدة كل $S = 6$ م (عند منسوب الجمالون، مكان الأوتار السفلية للجمالونات المعدنية النهارده) وكمرات طرفية على شكل L على الحائطين الطوال."}},{t:"steps",items:[{en:"$w_s = 5.0$ kN/m²: $Y = 30.0$, $X = 5.0\\times12^2/(8\\times1.6) = 56.25$, $P = 63.75$ kN/m; the slab needs only its minimum: 6Ø10/m on each face.",ar:"$w_s = 5.0$ kN/m²: $Y = 30.0$، و $X = 5.0\\times12^2/(8\\times1.6) = 56.25$، و $P = 63.75$ kN/m؛ والبلاطة محتاجة حدها الأدنى بس: 6Ø10/م على كل وش."},{en:"Ties: $T = 56.25\\times6 = 337.5$ kN → 970 mm² → 4Ø18. Columns: $R_{VL} = (7.0 + 30.0)\\times6 = 222$ kN, vertical only.",ar:"الشدادات: $T = 56.25\\times6 = 337.5$ kN ← 970 مم² ← 4Ø18. والأعمدة: $R_{VL} = (7.0 + 30.0)\\times6 = 222$ kN، رأسي بس."},{en:"End beams: vertical leg 250 × 600, $M = 133.2$ kN·m → 762 mm² (4Ø16); horizontal leg 250 × 700, $M = 202.5$ kN·m → 990 mm² (4Ø18). Half-span live load: only 1.8 kN·m/m.",ar:"الكمرات الطرفية: الرجل الرأسية 250 × 600، و $M = 133.2$ kN·m ← 762 مم² (4Ø16)؛ والرجل الأفقية 250 × 700، و $M = 202.5$ kN·m ← 990 مم² (4Ø18). والحمل الحي على نص البحر: 1.8 kN·m/m بس."},{en:"Without the ties each column would need 2025 kN·m. Against the two-hinged frame of the systems introduction (a 300 × 1000 beam with 917.3 kN·m at mid-span): 11.4 instead of 14.7 m³ of concrete per 6 m bay — 22% less.",ar:"من غير الشدادات كل عمود كان هيحتاج 2025 kN·m. وقصاد الإطار ذو المفصلين بتاع مقدمة الأنظمة (كمرة 300 × 1000 عليها 917.3 kN·m في النص): 11.4 بدل 14.7 م³ خرسانة لكل باكية 6 م — أقل بـ 22%."}]},{t:"widget",w:"building",props:{focus:"WT-1",tags:["footings","cols-g","beams-1","slab-1","cols-1","beams-2","slab-2","ws-columns","ws-trusses","sys-indet","sys-archslab"]}},{t:"quiz",q:{kind:"num",q:{en:"The workshop arch slab: force in each tie (kN)?",ar:"البلاطة المقوّسة للورشة: القوة في كل شداد (kN)؟"},answer:337.5,tol:.003,unit:"kN",explain:{en:"$X\\,S = 56.25\\times6 = 337.5$ kN.",ar:"$X\\,S = 56.25\\times6 = 337.5$ kN."}}}]}],quiz:[{kind:"num",q:{en:"An arch slab spans 16 m. The flattest rise allowed by the rule (m)?",ar:"بلاطة مقوّسة بحرها 16 م. أوطى ارتفاع بتسمح بيه القاعدة (م)؟"},answer:2,tol:.003,unit:"m",explain:{en:"$L/8 = 2.0$ m (the steepest, $L/6 = 2.67$ m).",ar:"$L/8 = 2.0$ م (والأعلى $L/6 = 2.67$ م)."}},{kind:"num",q:{en:"w_s = 6 kN/m², L = 12 m, h = 1.5 m. Thrust X (kN/m)?",ar:"w_s = 6 kN/m²، و L = 12 م، و h = 1.5 م. الدفع X (kN/m)؟"},answer:72,tol:.003,unit:"kN/m",explain:{en:"$6\\times144/(8\\times1.5) = 72$ kN/m.",ar:"$6\\times144/(8\\times1.5) = 72$ kN/m."}},{kind:"num",q:{en:"Springing reactions Y = 30 and X = 40 kN/m. Force P in the slab there (kN/m)?",ar:"ردود أفعال الارتكاز Y = 30 و X = 40 kN/m. القوة P في البلاطة هناك (kN/m)؟"},answer:50,tol:.003,unit:"kN/m",explain:{en:"$\\sqrt{30^2 + 40^2} = 50$ kN/m.",ar:"$\\sqrt{30^2 + 40^2} = 50$ kN/m."}},{kind:"mcq",q:{en:"Under the full load a parabolic arch slab has…",ar:"تحت الحمل الكامل البلاطة المقوّسة القطع المكافئ ليها…"},options:[{en:"practically no bending — only compression",ar:"تقريباً مفيش عزوم — ضغط بس"},{en:"its largest moment at the crown",ar:"أكبر عزم عند التاج"},{en:"tension at the springings",ar:"شد عند الارتكازات"}],answer:0,explain:{en:"The parabola is the thrust line of a load spread on plan.",ar:"القطع المكافئ هو خط الضغط لحمل مفروش على المسقط."}},{kind:"num",q:{en:"Live load p = 1.0 kN/m² on one half of a 16 m arch slab. Largest moment (kN·m/m)?",ar:"حمل حي p = 1.0 kN/m² على نص بلاطة مقوّسة 16 م. أكبر عزم (kN·m/m)؟"},answer:4,tol:.003,unit:"kN·m/m",explain:{en:"$1.0\\times16^2/64 = 4.0$ kN·m/m.",ar:"$1.0\\times16^2/64 = 4.0$ kN·m/m."}},{kind:"num",q:{en:"A 90 mm arch slab. Minimum steel in all, both faces (mm² per metre)?",ar:"بلاطة مقوّسة 90 مم. الحد الأدنى للحديد كله، الوشّين (مم² لكل متر)؟"},answer:720,tol:.003,unit:"mm²",explain:{en:"$0.008\\times1000\\times90 = 720$ mm²/m, 360 on each face.",ar:"$0.008\\times1000\\times90 = 720$ مم²/م، و 360 على كل وش."}},{kind:"tf",q:{en:"Without ties the columns of an arch-slab hall carry only vertical loads.",ar:"من غير شدادات أعمدة صالة البلاطة المقوّسة بتشيل أحمال رأسية بس."},answer:!1,explain:{en:"Each takes X·S at its head and bends: M = X·S·H at its base.",ar:"كل عمود بياخد X·S عند راسه وبينحني: M = X·S·H عند قاعدته."}},{kind:"num",q:{en:"Two equal arch slabs meet on an interior beam; each gives Y = 30 kN/m, the beam weighs 7 kN/m. Its vertical load (kN/m)?",ar:"بلاطتين مقوّستين متساويتين بيتقابلوا على كمرة وسطية؛ كل واحدة بتدّي Y = 30 kN/m، ووزن الكمرة 7 kN/m. حملها الرأسي (kN/m)؟"},answer:67,tol:.003,unit:"kN/m",explain:{en:"$7 + 2\\times30 = 67$ kN/m; the two thrusts cancel.",ar:"$7 + 2\\times30 = 67$ kN/m؛ والدفعين بيلغوا بعض."}}]};export{h as default};
